import{c as t,Q as o,j as a,m as r}from"./chunks/framework.DoOjWOm2.js";const d=JSON.parse('{"title":"Mobile App","description":"","frontmatter":{},"headers":[],"relativePath":"clients/mobile.md","filePath":"clients/mobile.md"}'),n={name:"clients/mobile.md"};function i(l,e,s,h,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="mobile-app" tabindex="-1">Mobile App <a class="header-anchor" href="#mobile-app" aria-label="Permalink to &quot;Mobile App&quot;">​</a></h1><p><strong>Phase:</strong> N (End-User Documentation) <strong>Step:</strong> N.13 <strong>Since:</strong> 0.18.0</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>The Phlix mobile app is available for both iOS and Android. Install it from your device&#39;s app store, open it, and enter your server URL or sign in with your Hub account. Minimum requirements: iOS 15+ or Android 10+.</p></div><h2 id="install-store-links" tabindex="-1">Install / Store Links <a class="header-anchor" href="#install-store-links" aria-label="Permalink to &quot;Install / Store Links&quot;">​</a></h2><ul><li><strong>Apple App Store:</strong> <a href="#">Phlix on the App Store</a></li><li><strong>Google Play:</strong> <a href="#">Phlix on Google Play</a></li><li><strong>Direct APK download:</strong> <a href="https://github.com/detain/phlix-mobile-client/releases" target="_blank" rel="noreferrer">github.com/detain/phlix-mobile-client/releases</a> — for Android devices outside the Play Store</li></ul><h2 id="platform-specific-install-steps" tabindex="-1">Platform-Specific Install Steps <a class="header-anchor" href="#platform-specific-install-steps" aria-label="Permalink to &quot;Platform-Specific Install Steps&quot;">​</a></h2><h3 id="ios" tabindex="-1">iOS <a class="header-anchor" href="#ios" aria-label="Permalink to &quot;iOS&quot;">​</a></h3><ol><li>Open the <strong>App Store</strong> on your iPhone or iPad.</li><li>Search for <strong>Phlix</strong> and tap <strong>Get</strong> to install.</li><li>For beta testing, join the <strong>TestFlight</strong> program via the link on the <a href="https://github.com/detain/phlix-mobile-client/releases" target="_blank" rel="noreferrer">releases page</a>.</li><li>Open Phlix from your home screen after installation.</li></ol><h3 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h3><ol><li>Open <strong>Google Play</strong> and search for <strong>Phlix</strong>.</li><li>Tap <strong>Install</strong> to download and install automatically.</li><li>For sideloading (outside Play Store): <ul><li>Download the APK from <a href="https://github.com/detain/phlix-mobile-client/releases" target="_blank" rel="noreferrer">github.com/detain/phlix-mobile-client/releases</a>.</li><li>Enable <strong>Install unknown apps</strong> in your device&#39;s security settings before running the APK.</li><li>Open the APK and follow the on-screen prompts.</li></ul></li></ol><h3 id="first-launch" tabindex="-1">First Launch <a class="header-anchor" href="#first-launch" aria-label="Permalink to &quot;First Launch&quot;">​</a></h3><p>On first launch, the app presents two options:</p><ul><li><strong>Enter Server URL</strong> — type your server&#39;s address directly (e.g., <code>http://192.168.1.100:32400</code> for local access or <code>https://your-domain.com</code> for remote access)</li><li><strong>Sign in with Hub</strong> — authenticate via your Phlix Hub account, which auto-discovers all servers linked to your hub</li></ul><p>Choose one and proceed. You can switch methods later in <strong>Settings → Account</strong>.</p><h2 id="setup-steps" tabindex="-1">Setup Steps <a class="header-anchor" href="#setup-steps" aria-label="Permalink to &quot;Setup Steps&quot;">​</a></h2><ol><li>After connecting, the app downloads your library list and starts displaying movies, shows, and other content.</li><li>On first connect, grant <strong>Camera</strong> permission if you want to scan barcodes or use photo-based search. Grant <strong>Storage</strong> permission if you want to download content for offline playback.</li><li>A background library sync begins automatically. New or updated items appear in your library over the next few minutes.</li><li>To manually refresh, pull down on the library list.</li></ol><h2 id="hub-connection" tabindex="-1">Hub Connection <a class="header-anchor" href="#hub-connection" aria-label="Permalink to &quot;Hub Connection&quot;">​</a></h2><p>Once the app is running and connected to a server, you can link it to your Hub account:</p><ol><li>Tap <strong>Settings</strong> (gear icon) in the top-right corner.</li><li>Tap <strong>Account → Sign in with Hub</strong>.</li><li>Enter the Hub URL (e.g., <code>https://hub.phlix.example.com</code>) and tap <strong>Continue</strong>.</li><li>Enter your Hub username and password, then tap <strong>Sign In</strong>.</li><li>If your Hub account manages multiple servers, a picker appears — select the server you want to use.</li></ol><p>The Hub connection allows you to access all of your Hub-linked servers without manually entering each URL, and enables secure remote playback when you are away from home.</p><h2 id="what-can-go-wrong" tabindex="-1">What Can Go Wrong <a class="header-anchor" href="#what-can-go-wrong" aria-label="Permalink to &quot;What Can Go Wrong&quot;">​</a></h2><h3 id="self-signed-certificate-error" tabindex="-1">Self-signed certificate error <a class="header-anchor" href="#self-signed-certificate-error" aria-label="Permalink to &quot;Self-signed certificate error&quot;">​</a></h3><p><strong>Symptom:</strong> On first launch, the app shows &quot;Unable to connect — certificate invalid&quot; immediately after entering the server URL.</p><p><strong>Fix:</strong> Your server is using a self-signed SSL certificate. Either replace it with a properly signed certificate (Let&#39;s Encrypt is free and automatic), or install your server&#39;s CA certificate on the mobile device. For local-only use, you can also connect over HTTP by using <code>http://</code> instead of <code>https://</code> in the server URL.</p><h3 id="server-not-reachable-when-away-from-home" tabindex="-1">Server not reachable when away from home <a class="header-anchor" href="#server-not-reachable-when-away-from-home" aria-label="Permalink to &quot;Server not reachable when away from home&quot;">​</a></h3><p><strong>Symptom:</strong> The app times out or shows &quot;Server unreachable&quot; when you are on mobile data or a different Wi-Fi network, even though it works fine at home.</p><p><strong>Fix:</strong> Use the Hub relay URL (from the sign-in-with-Hub flow) for remote access — the Hub relay handles the connection tunnel automatically. For direct access, configure port forwarding on your router for TCP port 32400, or set up a Tailscale VPN to create a private tunnel between your mobile device and your home network.</p><h3 id="hub-login-fails" tabindex="-1">Hub login fails <a class="header-anchor" href="#hub-login-fails" aria-label="Permalink to &quot;Hub login fails&quot;">​</a></h3><p><strong>Symptom:</strong> Tapping &quot;Sign in with Hub&quot; and entering your credentials returns &quot;Authentication failed.&quot;</p><p><strong>Fix:</strong> Verify your Hub username and password. Confirm the Hub URL is entered without a trailing slash (e.g., <code>https://hub.phlix.example.com</code> not <code>https://hub.phlix.example.com/</code>). If you have forgotten your Hub password, use the password reset flow on the Hub login page.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./web.html">Web client</a> — access from any browser without installing software</li><li><a href="./roku.html">Roku</a> — living room streaming on Roku devices</li><li><a href="./tizen.html">Tizen</a> — Samsung Smart TV app</li></ul>',32)])])}const g=t(n,[["render",i]]);export{d as __pageData,g as default};
